sql:
SELECT COUNT(*) AS value
FROM business.orders AS o
WHERE (o.ordered_at >= CAST('2026-09-01T00:00:00Z' AS TIMESTAMPTZ) AND o.ordered_at < CAST('2026-10-01T00:00:00Z' AS TIMESTAMPTZ));

